var CIG_PER_PACK=20, MIN_PER_CIG=11; // 研究估算每支约 11 分钟寿命
function costPerYear(packsPerDay, price){ return packsPerDay*price*365; }
function cost(packsPerDay, price, years){ return costPerYear(packsPerDay,price)*years; }
function packYears(packsPerDay, years){ return packsPerDay*years; }
function lifeLostMin(packsPerDay, years){ return packsPerDay*CIG_PER_PACK*365*years*MIN_PER_CIG; }
function savingsIfQuit(packsPerDay, price, futureYears){ return cost(packsPerDay,price,futureYears); }
var EXPORTS={CIG_PER_PACK:CIG_PER_PACK, MIN_PER_CIG:MIN_PER_CIG, costPerYear:costPerYear, cost:cost, packYears:packYears, lifeLostMin:lifeLostMin, savingsIfQuit:savingsIfQuit};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SmokingForgePure = EXPORTS; }
